/* ---------- Util waktu WIB ---------- */
function wibParts(d) {
  const fmt = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Jakarta', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false, weekday: 'long',
  });
  const parts = {};
  fmt.formatToParts(d).forEach((p) => { parts[p.type] = p.value; });
  return parts;
}
const pad = (n) => (n < 10 ? '0' : '') + n;
const dateStrOf = (p) => `${p.year}-${p.month}-${p.day}`;
const todayWIB = () => dateStrOf(wibParts(new Date()));
function shiftDateStr(dateStr, deltaDays) {
  const a = dateStr.split('-').map(Number);
  const dt = new Date(Date.UTC(a[0], a[1] - 1, a[2] + deltaDays));
  return `${dt.getUTCFullYear()}-${pad(dt.getUTCMonth() + 1)}-${pad(dt.getUTCDate())}`;
}
function minutesNowWIB() {
  const p = wibParts(new Date());
  return Number(p.hour) * 60 + Number(p.minute);
}
const DAY_NAMES = { Monday: 'Senin', Tuesday: 'Selasa', Wednesday: 'Rabu', Thursday: 'Kamis', Friday: 'Jumat', Saturday: 'Sabtu', Sunday: 'Minggu' };
const MONTH_NAMES = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
function fmtDateLong(dateStr) {
  if (!dateStr) return '';
  const a = dateStr.split('-').map(Number);
  const dt = new Date(Date.UTC(a[0], a[1] - 1, a[2]));
  const days = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
  return `${days[dt.getUTCDay()]}, ${a[2]} ${MONTH_NAMES[a[1] - 1]} ${a[0]}`;
}
const fmtNum = (n) => Number(n).toLocaleString('id-ID', { maximumFractionDigits: 2 });
function weekRange(dateStr) {
  const a = dateStr.split('-').map(Number);
  const dt = new Date(Date.UTC(a[0], a[1] - 1, a[2]));
  const dow = dt.getUTCDay(); // 0=Minggu .. 6=Sabtu
  const sinceMonday = (dow + 6) % 7;
  const start = shiftDateStr(dateStr, -sinceMonday);
  return { start, end: shiftDateStr(start, 6) };
}

/* ---------- Aturan jendela input ----------
   Shift 1 (07.30–20.30): diisi pada tanggal kerja itu sendiri, tutup 21.00 WIB.
   Shift 2 (20.30–07.30): HANYA diisi 07.30–08.00 pagi berikutnya, tercatat untuk hari kerja sebelumnya.
   Shift kosong mengikuti Shift 1. */
function windowCheck(shift, workDate) {
  const s = shift === 2 ? 2 : 1;
  const today = todayWIB();
  const mins = minutesNowWIB();
  if (s === 1) {
    if (workDate !== today) {
      return {
        open: false,
        msg: workDate < today
          ? `Jendela Shift 1 untuk ${fmtDateLong(workDate)} sudah ditutup (batas 21.00 di hari kerja).`
          : 'Tanggal kerja belum tiba — Shift 1 hanya bisa diisi pada hari kerjanya.',
      };
    }
    if (mins > 21 * 60) return { open: false, msg: 'Jendela Shift 1 sudah ditutup pukul 21.00 WIB.' };
    return { open: true, msg: '' };
  }
  const yesterday = shiftDateStr(today, -1);
  if (workDate !== yesterday) {
    return { open: false, msg: `Shift 2 diisi keesokan hari untuk tanggal kerja sebelumnya (${fmtDateLong(yesterday)}).` };
  }
  if (mins < 7 * 60 + 30) return { open: false, msg: 'Jendela Shift 2 dibuka pukul 07.30 WIB.' };
  if (mins > 8 * 60) return { open: false, msg: 'Jendela Shift 2 sudah ditutup pukul 08.00 WIB.' };
  return { open: true, msg: '' };
}
// Tanggal kerja yang akan tercatat untuk shift yang dipilih (mode karyawan).
function workDateForShift(shift) {
  return shift === 2 ? shiftDateStr(todayWIB(), -1) : todayWIB();
}

const UNIT_ORDER = ['pcs', 'dus', 'roll', 'ball', 'pack'];
const UNITS = ['pcs', 'roll', 'dus', 'pack', 'ball'];

/* ---------- Mode Master: PIN hanya disimpan sebagai hash (djb2) ---------- */
const MASTER_PIN_HASH = 2088330068;
function pinHash(s) {
  let h = 5381;
  for (let i = 0; i < s.length; i++) { h = ((h << 5) + h + s.charCodeAt(i)) >>> 0; }
  return h;
}

