function parseNames(raw, employees) {
  const out = [];
  const seen = {};
  String(raw || '').split(',').forEach((part) => {
    const typed = part.trim().replace(/\s+/g, ' ');
    if (!typed) return;
    const canon = typed.toUpperCase();
    const name = employees.indexOf(canon) > -1 ? canon : typed;
    if (!seen[name]) { seen[name] = true; out.push(name); }
  });
  return out;
}

function totalsOf(list) {
  const t = {};
  list.forEach((e) => { if (e.qty !== null && e.qty !== undefined && e.unit) t[e.unit] = (t[e.unit] || 0) + e.qty; });
  return t;
}
function totalsText(t) {
  const parts = UNIT_ORDER.filter((u) => t[u]).map((u) => `${fmtNum(t[u])} ${u}`);
  return parts.length ? parts.join(' · ') : '—';
}
// Peringkat per satuan: setiap nama dalam catatan kelompok menerima nilai penuh catatan itu.
function rankingGroups(list) {
  const out = [];
  UNIT_ORDER.forEach((u) => {
    const per = {};
    list.forEach((e) => {
      if (e.qty === null || e.qty === undefined || e.unit !== u) return;
      e.names.forEach((n) => { per[n] = (per[n] || 0) + e.qty; });
    });
    const names = Object.keys(per);
    if (!names.length) return;
    names.sort((a, b) => per[b] - per[a]);
    const groups = [];
    names.forEach((n) => {
      const last = groups[groups.length - 1];
      if (last && last.val === per[n]) last.names.push(n);
      else groups.push({ val: per[n], names: [n] });
    });
    out.push({ unit: u, groups });
  });
  return out;
}

export default function Page() {
  const [doc, setDoc] = useState({ employees: [], entries: [], driverEntries: [] });
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [tab, setTab] = useState('beranda');
  const [now, setNow] = useState(() => new Date());
  const [toast, setToast] = useState('');
  const toastTimer = useRef(null);

  // Mode Master — hanya di memori, hilang saat halaman di-reload.
  const [masterOn, setMasterOn] = useState(false);
  const [pinPanel, setPinPanel] = useState(false);
  const [pin, setPin] = useState('');
  const [pinMsg, setPinMsg] = useState('');

  // Form Input Hasil
  const [fDate, setFDate] = useState('');
  const [fTime, setFTime] = useState('');
  const [fShift, setFShift] = useState(1); // 1 | 2 | '' (kosong = mengikuti Shift 1)
  const [fNames, setFNames] = useState('');
  const [fMachine, setFMachine] = useState('');
  const [fJob, setFJob] = useState('');
  const [fMode, setFMode] = useState('qty'); // 'qty' | 'note'
  const [fQty, setFQty] = useState('');
  const [fUnit, setFUnit] = useState('pcs');
  const [fNote, setFNote] = useState('');
  const [fMsg, setFMsg] = useState({ kind: '', text: '' });
  const [editId, setEditId] = useState(null);

  // Form Driver
  const [dDate, setDDate] = useState('');
  const [dName, setDName] = useState('');
  const [dDest, setDDest] = useState('');
  const [dVeh, setDVeh] = useState('');
  const [dNote, setDNote] = useState('');
  const [dMsg, setDMsg] = useState({ kind: '', text: '' });
  const [dEditId, setDEditId] = useState(null);

  // Beranda & Rekap
  const [leadPeriod, setLeadPeriod] = useState('hari'); // hari | minggu | bulan
  const [rekapMode, setRekapMode] = useState('day'); // day | week
  const [rdate, setRdate] = useState('');
  const [rsearch, setRsearch] = useState('');
  const [rmachine, setRmachine] = useState('');

  const loadedRef = useRef(false);
  const docRef = useRef(doc);
  docRef.current = doc;

  function showToast(msg) {
    setToast(msg);
    clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(''), 2600);
  }

  // Muat data saat mount; daftarkan service worker.
  useEffect(() => {
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.register('/sw.js').catch(() => {});
    }
    fetch('/api/data')
      .then((r) => r.json())
      .then((d) => {
        setDoc({
          employees: Array.isArray(d.employees) ? d.employees : [],
          entries: Array.isArray(d.entries) ? d.entries : [],
          driverEntries: Array.isArray(d.driverEntries) ? d.driverEntries : [],
        });
        loadedRef.current = true;
        setLoading(false);
      })
      .catch(() => { loadedRef.current = true; setLoading(false); });
    const t = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(t);
  }, []);

  // Tanggal default form mengikuti hari ini (WIB).
  useEffect(() => {
    if (!loading) {
      if (!fDate) setFDate(todayWIB());
      if (!dDate) setDDate(todayWIB());
      if (!rdate) setRdate(todayWIB());
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loading]);

  async function saveDoc(next) {
    setDoc(next);
    if (!loadedRef.current) return;
    setSaving(true);
    try {
      await fetch('/api/data', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(next),
      });
    } catch { /* simpan gagal: data tetap di layar, coba lagi saat perubahan berikut */ }
    setSaving(false);
  }

  const { employees, entries, driverEntries } = doc;

  /* ---------- Jam & status jendela ---------- */
  const wib = wibParts(now);
  const clockTime = `${wib.hour === '24' ? '00' : wib.hour}:${wib.minute}:${wib.second}`;
  const clockDate = `${DAY_NAMES[wib.weekday] || wib.weekday}, ${Number(wib.day)} ${MONTH_NAMES[Number(wib.month) - 1]} ${wib.year}`;
  const s1Open = masterOn || windowCheck(1, todayWIB()).open;
  const s2Open = masterOn || windowCheck(2, shiftDateStr(todayWIB(), -1)).open;

  /* ---------- Mode Master ---------- */
  function setMaster(on) {
    setMasterOn(on);
    if (!on) { setPinPanel(false); setPin(''); setPinMsg(''); }
  }
  function tryUnlock() {
    if (pinHash(pin.trim()) === MASTER_PIN_HASH) {
      setPinPanel(false);
      setPin('');
      setPinMsg('');
      setMaster(true);
      showToast('Mode Master aktif — tanggal & waktu bisa diatur manual.');
    } else {
      setPinMsg('PIN salah — coba lagi.');
    }
  }

  /* ---------- Form Input Hasil ---------- */
  // Tanggal kerja yang tercatat: mode karyawan mengikuti shift yang dipilih; master bebas pilih.
  const effWorkDate = masterOn ? (fDate || todayWIB()) : workDateForShift(fShift);
  const effShift = fShift === 2 ? 2 : 1;

  function resetWorkForm(keepDateShift) {
    setFNames('');
    setFMachine('');
    setFJob('');
    setFQty('');
    setFNote('');
    setFMode('qty');
    setFTime('');
    setEditId(null);
    if (!keepDateShift) { setFShift(1); }
    setFMsg({ kind: '', text: '' });
  }

  function submitWork(e) {
    e.preventDefault();
    setFMsg({ kind: '', text: '' });
    const date = effWorkDate;
    const names = parseNames(fNames, employees);
    const job = fJob.trim();
    const machine = fMachine.trim();
    const note = fNote.trim();
    if (!date) return setFMsg({ kind: 'err', text: 'Tanggal kerja wajib diisi.' });
    if (!names.length) return setFMsg({ kind: 'err', text: 'Ketik minimal satu nama karyawan.' });
    if (!job) return setFMsg({ kind: 'err', text: 'Pekerjaan wajib diisi.' });
    let qty = null;
    if (fMode === 'qty') {
      if (fQty === '' || isNaN(Number(fQty)) || Number(fQty) < 0) {
        return setFMsg({ kind: 'err', text: 'Jumlah hasil wajib diisi dengan angka, atau pilih mode “Tanpa hasil (keterangan saja)”.' });
      }
      qty = Number(fQty);
    } else if (!note) {
      return setFMsg({ kind: 'err', text: 'Mode “Tanpa hasil (keterangan saja)” wajib diisi Keterangan.' });
    }
    if (!masterOn) {
      const chk = windowCheck(fShift, date);
      if (!chk.open) return setFMsg({ kind: 'err', text: chk.msg });
    }
    const wtime = masterOn ? (fTime || '') : '';
    const rec = {
      id: editId || uid(), date, shift: effShift, names, job, machine,
      qty, unit: qty === null ? null : fUnit, note, time: wtime,
    };
    const nextEntries = editId
      ? entries.map((x) => (x.id === editId ? rec : x))
      : [...entries, rec];
    saveDoc({ ...docRef.current, entries: nextEntries });
    const wasEdit = !!editId;
    resetWorkForm(true);
    setFMsg({ kind: 'ok', text: wasEdit ? `Diperbarui: ${job} — ${names.join(', ')} (Shift ${effShift}).` : `Tercatat: ${job} — ${names.join(', ')} (Shift ${effShift}).` });
    showToast(wasEdit ? 'Catatan diperbarui.' : 'Catatan hasil kerja ditambahkan.');
  }

  function startEditEntry(en) {
    setEditId(en.id);
    setFDate(en.date);
    setFTime(en.time || '');
    setFShift(en.shift);
    setFNames(en.names.join(', '));
    setFMachine(en.machine || '');
    setFJob(en.job);
    setFMode(en.qty === null || en.qty === undefined ? 'note' : 'qty');
    setFQty(en.qty === null || en.qty === undefined ? '' : String(en.qty));
    setFUnit(en.unit || 'pcs');
    setFNote(en.note || '');
    setFMsg({ kind: '', text: '' });
    setTab('input');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  function deleteEntry(id) {
    saveDoc({ ...docRef.current, entries: entries.filter((x) => x.id !== id) });
    showToast('Catatan dihapus.');
  }

  /* ---------- Form Driver ---------- */
  function submitDriver(e) {
    e.preventDefault();
    setDMsg({ kind: '', text: '' });
    const date = masterOn ? (dDate || todayWIB()) : todayWIB();
    const name = dName.trim();
    const dest = dDest.trim();
    const veh = dVeh.trim();
    const note = dNote.trim();
    if (!date) return setDMsg({ kind: 'err', text: 'Tanggal wajib diisi.' });
    if (!name) return setDMsg({ kind: 'err', text: 'Nama driver / helper (kenek) wajib diisi.' });
    if (!dest) return setDMsg({ kind: 'err', text: 'Tujuan pengiriman wajib diisi.' });
    if (!masterOn) {
      if (minutesNowWIB() > 21 * 60) {
        return setDMsg({ kind: 'err', text: 'Pengiriman driver hanya bisa dicatat sampai pukul 21.00 WIB pada hari yang sama.' });
      }
    }
    const rec = { id: dEditId || uid(), date, name, dest, veh, note };
    const nextDrivers = dEditId
      ? driverEntries.map((x) => (x.id === dEditId ? rec : x))
      : [...driverEntries, rec];
    saveDoc({ ...docRef.current, driverEntries: nextDrivers });
    const wasEdit = !!dEditId;
    setDName(''); setDDest(''); setDVeh(''); setDNote(''); setDEditId(null);
    setDMsg({ kind: 'ok', text: wasEdit ? `Diperbarui: pengiriman oleh ${name} ke ${dest}.` : `Tercatat: pengiriman oleh ${name} ke ${dest}.` });
    showToast(wasEdit ? 'Catatan pengiriman diperbarui.' : 'Catatan pengiriman ditambahkan.');
  }

  function startEditDriver(d) {
    setDEditId(d.id);
    setDDate(d.date);
    setDName(d.name);
    setDDest(d.dest);
    setDVeh(d.veh || '');
    setDNote(d.note || '');
    setDMsg({ kind: '', text: '' });
    setTab('driver');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  function deleteDriver(id) {
    saveDoc({ ...docRef.current, driverEntries: driverEntries.filter((x) => x.id !== id) });
    showToast('Catatan pengiriman dihapus.');
  }

  /* ---------- Beranda: leaderboard + riwayat ---------- */
  const leadRange = useMemo(() => {
    const t = todayWIB();
    if (leadPeriod === 'minggu') {
      const w = weekRange(t);
      return { start: w.start, end: w.end, label: `${fmtDateLong(w.start)} – ${fmtDateLong(w.end)}` };
    }
    if (leadPeriod === 'bulan') {
      const start = `${t.slice(0, 8)}01`;
      const y = Number(t.slice(0, 4)) + (t.slice(5, 7) === '12' ? 1 : 0);
      const nmFirst = t.slice(5, 7) === '12' ? `${y}-01-01` : `${t.slice(0, 5)}${pad(Number(t.slice(5, 7)) + 1)}-01`;
      return { start, end: shiftDateStr(nmFirst, -1), label: `${MONTH_NAMES[Number(t.slice(5, 7)) - 1]} ${t.slice(0, 4)}` };
    }
    return { start: t, end: t, label: fmtDateLong(t) };
  }, [leadPeriod]);
  const leadEntries = useMemo(
    () => entries.filter((e) => e.date >= leadRange.start && e.date <= leadRange.end),
    [entries, leadRange]
  );
  const leadReported = useMemo(() => {
    const s = new Set();
    leadEntries.forEach((e) => e.names.forEach((n) => s.add(n)));
    return s.size;
  }, [leadEntries]);
  const leadRank = useMemo(() => rankingGroups(leadEntries), [leadEntries]);
  const historySorted = useMemo(
    () => [...entries].sort((a, b) => (a.date !== b.date ? (a.date < b.date ? 1 : -1) : 0)),
    [entries]
  );

  /* ---------- Rekap ---------- */
  const period = useMemo(() => {
    const base = rdate || todayWIB();
    if (rekapMode === 'week') {
      const w = weekRange(base);
      const dates = [];
      for (let i = 0; i < 7; i++) dates.push(shiftDateStr(w.start, i));
      return { mode: 'week', base, start: w.start, end: w.end, dates, label: `${fmtDateLong(w.start)} – ${fmtDateLong(w.end)}` };
    }
    return { mode: 'day', base, start: base, end: base, dates: [base], label: fmtDateLong(base) };
  }, [rekapMode, rdate]);
  const periodFileSlug = period.mode === 'week' ? `mingguan-${period.start}-sd-${period.end}` : period.start;
  const qName = rsearch.trim().toLowerCase();
  const qMachine = rmachine.trim().toLowerCase();
  const matchesSearch = (e) => {
    if (qName && !e.names.some((n) => String(n).toLowerCase().includes(qName))) return false;
    if (qMachine && String(e.machine || '').toLowerCase().indexOf(qMachine) === -1) return false;
    return true;
  };
  const periodEntries = useMemo(
    () => entries
      .filter((e) => period.dates.indexOf(e.date) > -1 && matchesSearch(e))
      .sort((a, b) => (a.date !== b.date ? (a.date < b.date ? -1 : 1) : a.shift - b.shift)),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [entries, period, qName, qMachine]
  );
  const periodDrivers = useMemo(
    () => driverEntries
      .filter((d) => period.dates.indexOf(d.date) > -1)
      .sort((a, b) => (a.date < b.date ? -1 : (a.date > b.date ? 1 : 0))),
    [driverEntries, period]
  );
  const s1 = periodEntries.filter((e) => e.shift === 1);
  const s2 = periodEntries.filter((e) => e.shift === 2);
  const rekapRank = useMemo(() => rankingGroups(periodEntries), [periodEntries]);

  /* ---------- Laporan & unduhan (mengikuti periode + filter aktif) ---------- */
  function buildReport() {
    const isWeek = period.mode === 'week';
    const lines = [];
    lines.push(isWeek
      ? `👷 Laporan Hasil Kerja — Per Minggu (Senin–Minggu) — ${period.label}`
      : `👷 Laporan Hasil Kerja — Per Hari — ${period.label}`);
    if (qName) lines.push(`🔎 Pencarian nama karyawan: “${rsearch.trim()}” — hanya catatan yang memuat nama itu.`);
    if (qMachine) lines.push(`🔎 Pencarian nama mesin: “${rmachine.trim()}” — hanya catatan dengan nama mesin itu.`);
    lines.push('');
    const block = (title, list) => {
      lines.push(`👷 ${title}${isWeek ? ` — Minggu ${period.label}` : ` — ${period.label}`}`);
      lines.push('');
      if (!list.length) { lines.push('Tidak ada catatan.'); lines.push(''); return; }
      list.forEach((e, i) => {
        const parts = [`${i + 1}. ${isWeek ? `[${e.date}] ` : ''}${e.machine ? `Mesin: ${e.machine} — ` : ''}${e.job} — ${e.names.join(', ')} — Shift ${e.shift}${e.time ? ` — Pukul ${e.time.replace(':', '.')}` : ''}`];
        if (e.note) parts.push(`Keterangan: ${e.note}`);
        parts.push(`Hasil: ${e.qty !== null && e.qty !== undefined ? `${fmtNum(e.qty)} ${e.unit}` : 'tanpa hasil (keterangan saja)'}`);
        lines.push(parts.join(' — '));
      });
      lines.push('');
      lines.push(`📊 Total ${title}: ${totalsText(totalsOf(list))}`);
      lines.push('');
    };
    if (s2.length && !s1.length) block('Shift 2', s2);
    else if (s1.length && s2.length) { block('Shift 1', s1); block('Shift 2', s2); }
    else block('Shift 1', s1);
    lines.push(isWeek ? '🏆 Peringkat minggu ini (per satuan):' : '🏆 Peringkat hari ini (per satuan):');
    let anyRank = false;
    rekapRank.forEach(({ unit, groups }) => {
      anyRank = true;
      lines.push(`${unit}: ${groups.map((g, i) => `${i + 1}) ${g.names.join(', ')} — ${fmtNum(g.val)}`).join(' · ')}`);
    });
    if (!anyRank) lines.push('Belum ada hasil terukur.');
    lines.push('');
    lines.push('🚚 Pengiriman Driver');
    if (!periodDrivers.length) lines.push(isWeek ? 'Minggu ini tidak ada pengiriman driver yang dicatat.' : 'Hari ini tidak ada pengiriman driver yang dicatat.');
    periodDrivers.forEach((d, i) => {
      lines.push(`${i + 1}. ${isWeek ? `[${d.date}] ` : ''}${d.name} → ${d.dest}${d.veh ? ` (${d.veh})` : ''}${d.note ? ` — ${d.note}` : ''}`);
    });
    lines.push('');
    const withQty = periodEntries.filter((e) => e.qty !== null && e.qty !== undefined).length;
    lines.push(`📝 Ringkasan: ${periodEntries.length} catatan — ${withQty} catatan dengan hasil dan ${periodEntries.length - withQty} catatan tanpa hasil (keterangan saja). Total gabungan: ${totalsText(totalsOf(periodEntries))}.`);
    return lines.join('\n');
  }
  function downloadFile(name, text, type) {
    const blob = new Blob([text], { type: type || 'text/plain;charset=utf-8' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = name;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 400);
  }
  function downloadTxt() {
    downloadFile(`laporan-hasil-kerja-${periodFileSlug}.txt`, buildReport());
    showToast('Laporan diunduh.');
  }
  function copyReport() {
    const text = buildReport();
    const done = () => showToast('Laporan disalin — siap ditempel ke chat.');
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done, () => { fallbackCopy(text); done(); });
    } else { fallbackCopy(text); done(); }
  }
  function fallbackCopy(text) {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); } catch {}
    ta.remove();
  }
  function downloadCsv() {
    const esc = (v) => `"${String(v == null ? '' : v).replace(/"/g, '""')}"`;
    const rows = [['tanggal', 'jenis', 'shift', 'waktu', 'karyawan', 'nama_mesin', 'pekerjaan_tujuan', 'jumlah', 'satuan', 'keterangan']];
    periodEntries.forEach((e) => {
      rows.push([e.date, 'hasil kerja', e.shift, e.time || '', e.names.join(', '), e.machine || '', e.job, e.qty === null || e.qty === undefined ? '' : e.qty, e.unit || '', e.note || '']);
    });
    periodDrivers.forEach((d) => {
      rows.push([d.date, 'driver', '', '', d.name, '', d.dest, '', '', (d.veh ? `${d.veh} — ` : '') + (d.note || '')]);
    });
    downloadFile(`hasil-kerja-${periodFileSlug}.csv`, rows.map((r) => r.map(esc).join(',')).join('\n'), 'text/csv;charset=utf-8');
    showToast('CSV diunduh.');
  }
  function downloadXlsx() {
    try {
      const isWeek = period.mode === 'week';
      const wb = XLSX.utils.book_new();
      wb.Props = {
        Title: `Hasil Kerja Karyawan — ${period.label}`,
        Subject: 'Rekap Hasil Kerja Karyawan PT Meleo Mahkota Abadi',
        Creator: 'Hasil Kerja Karyawan — PT Meleo Mahkota Abadi',
        CreatedDate: new Date(),
      };
      const aoaWork = [['Tanggal', 'Shift', 'Waktu', 'Karyawan', 'Nama Mesin', 'Pekerjaan', 'Jumlah', 'Satuan', 'Keterangan']];
      periodEntries.forEach((e) => {
        aoaWork.push([e.date, e.shift, e.time || '', e.names.join(', '), e.machine || '', e.job, e.qty === null || e.qty === undefined ? '' : e.qty, e.unit || '', e.note || '']);
      });
      if (!periodEntries.length) {
        aoaWork.push([period.start, '', '', '', '', isWeek ? 'Belum ada catatan hasil kerja pada minggu ini' : 'Belum ada catatan hasil kerja pada tanggal ini', '', '', '']);
      }
      const wsWork = XLSX.utils.aoa_to_sheet(aoaWork);
      wsWork['!cols'] = [{ wch: 12 }, { wch: 8 }, { wch: 8 }, { wch: 30 }, { wch: 22 }, { wch: 38 }, { wch: 12 }, { wch: 10 }, { wch: 44 }];
      if (periodEntries.length) wsWork['!autofilter'] = { ref: `A1:I${aoaWork.length}` };
      XLSX.utils.book_append_sheet(wb, wsWork, 'Hasil Kerja');

      const aoaDrv = [['Tanggal', 'Nama Driver / Helper', 'Tujuan Pengiriman', 'Kendaraan / No. Polisi', 'Keterangan']];
      periodDrivers.forEach((d) => {
        aoaDrv.push([d.date, d.name, d.dest, d.veh || '', d.note || '']);
      });
      if (!periodDrivers.length) {
        aoaDrv.push([period.start, '', isWeek ? 'Tidak ada pengiriman driver yang dicatat pada minggu ini' : 'Tidak ada pengiriman driver yang dicatat pada tanggal ini', '', '']);
      }
      const wsDrv = XLSX.utils.aoa_to_sheet(aoaDrv);
      wsDrv['!cols'] = [{ wch: 12 }, { wch: 26 }, { wch: 42 }, { wch: 24 }, { wch: 44 }];
      if (periodDrivers.length) wsDrv['!autofilter'] = { ref: `A1:E${aoaDrv.length}` };
      XLSX.utils.book_append_sheet(wb, wsDrv, 'Driver');

      const aoaSum = [];
      aoaSum.push(['Rekap Hasil Kerja Karyawan — PT Meleo Mahkota Abadi']);
      aoaSum.push([isWeek ? 'Periode (per minggu)' : 'Tanggal', period.label]);
      if (qName) aoaSum.push(['Pencarian nama karyawan', rsearch.trim()]);
      if (qMachine) aoaSum.push(['Pencarian nama mesin', rmachine.trim()]);
      aoaSum.push([]);
      aoaSum.push(['Ringkasan']);
      aoaSum.push(['Jumlah catatan Shift 1', s1.length, 'catatan']);
      aoaSum.push(['Jumlah catatan Shift 2', s2.length, 'catatan']);
      aoaSum.push(['Jumlah catatan gabungan', periodEntries.length, 'catatan']);
      aoaSum.push(['Jumlah pengiriman driver', periodDrivers.length, 'catatan']);
      aoaSum.push([]);
      aoaSum.push(['Total Hasil']);
      aoaSum.push(['Shift 1', totalsText(totalsOf(s1))]);
      aoaSum.push(['Shift 2', totalsText(totalsOf(s2))]);
      aoaSum.push(['Gabungan Shift 1 + 2', totalsText(totalsOf(periodEntries))]);
      aoaSum.push([]);
      aoaSum.push(['Total per Satuan (gabungan)']);
      aoaSum.push(['Satuan', 'Total']);
      const totAll = totalsOf(periodEntries);
      let anyTot = false;
      UNIT_ORDER.forEach((u) => { if (totAll[u]) { anyTot = true; aoaSum.push([u, totAll[u]]); } });
      if (!anyTot) aoaSum.push(['—', 'Belum ada hasil terukur']);
      aoaSum.push([]);
      aoaSum.push(['Peringkat per Karyawan (gabungan Shift 1 + 2)']);
      aoaSum.push(['Catatan: setiap nama dalam catatan kelompok menerima nilai penuh catatan itu, sama seperti di Rekap.']);
      let anyRank = false;
      rekapRank.forEach(({ unit, groups }) => {
        anyRank = true;
        aoaSum.push([]);
        aoaSum.push([`Satuan: ${unit}`]);
        aoaSum.push(['Peringkat', 'Karyawan', 'Total', 'Satuan']);
        groups.forEach((g, i) => { aoaSum.push([i + 1, g.names.join(', '), g.val, unit]); });
      });
      if (!anyRank) aoaSum.push([isWeek ? 'Belum ada hasil terukur pada minggu ini.' : 'Belum ada hasil terukur pada tanggal ini.']);
      const wsSum = XLSX.utils.aoa_to_sheet(aoaSum);
      wsSum['!cols'] = [{ wch: 42 }, { wch: 38 }, { wch: 16 }, { wch: 12 }];
      wsSum['!merges'] = [{ s: { r: 0, c: 0 }, e: { r: 0, c: 3 } }];
      XLSX.utils.book_append_sheet(wb, wsSum, 'Ringkasan');

      XLSX.writeFile(wb, `hasil-kerja-${periodFileSlug}.xlsx`);
      showToast('File Excel (.xlsx) diunduh — 3 sheet: Hasil Kerja, Driver, Ringkasan.');
    } catch {
      showToast('Gagal membuat file Excel — coba lagi, atau pakai Unduh CSV.');
    }
  }

  /* ---------- Tampilan ---------- */
  const entryCard = (e, showDate, onEdit, onDelete) => (
    <div key={e.id} style={S.entry}>
      {showDate && <span style={S.dateTag}>{fmtDateLong(e.date)}</span>}
      <div style={S.entryTop}>
        <div>
          {e.machine ? <div style={S.machine}>Mesin: {e.machine}</div> : null}
          <div style={S.job}>{e.job}</div>
          <div style={S.who}>{e.names.join(', ')} — Shift {e.shift}{e.time ? ` · Pukul ${e.time.replace(':', '.')}` : ''}</div>
        </div>
        {e.qty !== null && e.qty !== undefined
          ? <span style={S.qty}>{fmtNum(e.qty)} {e.unit}</span>
          : <span style={S.qtyNone}>tanpa hasil</span>}
      </div>
      {e.note ? <div style={S.note}>Keterangan: {e.note}</div> : null}
      <div style={{ display: 'flex', gap: 8, marginTop: 10 }}>
        {onEdit && <button type="button" style={S.btnSec} onClick={() => onEdit(e)}>Edit</button>}
        {masterOn && onDelete && <button type="button" style={S.btnDanger} onClick={() => onDelete(e.id)}>Hapus</button>}
      </div>
    </div>
  );

  const rankBlock = (rank) => {
    if (!rank.length) return <div style={S.empty}>Belum ada hasil terukur pada periode ini.</div>;
    return rank.map(({ unit, groups }) => (
      <div key={unit}>
        <div style={S.rankUnit}>{unit}</div>
        <ol style={{ margin: '0 0 8px', paddingLeft: 0, listStyle: 'none' }}>
          {groups.map((g, i) => (
            <li key={i} style={S.rankLi}>
              <span>{i + 1}. {g.names.join(', ')}</span>
              <span style={{ fontWeight: 700 }}>{fmtNum(g.val)} {unit}</span>
            </li>
          ))}
        </ol>
      </div>
    ));
  };

  if (loading) {
    return (
      <div style={S.main}>
        <div style={S.col}><p style={S.lead}>Memuat data hasil kerja…</p></div>
      </div>
    );
  }

  const tabs = [
    { id: 'beranda', label: 'Beranda' },
    { id: 'input', label: 'Input Hasil' },
    { id: 'driver', label: 'Driver' },
    { id: 'rekap', label: 'Hasil (Rekap)' },
  ];

  return (
    <div>
      <header style={S.header}>
        <div style={S.headerInner}>
          <Logo size={44} />
          <div>
            <div style={S.brandName}>PT. Meleo Mahkota Abadi</div>
            <div style={S.brandSub}>Hasil Kerja Karyawan</div>
          </div>
          <div style={{ marginLeft: 'auto', textAlign: 'right' }}>
            <div style={{ fontSize: 18, fontWeight: 800, color: '#111827', fontFamily: 'ui-monospace, monospace' }}>{clockTime}</div>
            <div style={{ fontSize: 12, color: '#6b7280' }}>{clockDate} · WIB</div>
          </div>
          <nav style={S.nav}>
            {tabs.map((t) => (
              <button key={t.id} type="button" style={S.navBtn(tab === t.id)} onClick={() => setTab(t.id)}>
                {t.label}
              </button>
            ))}
          </nav>
        </div>
        <div style={{ maxWidth: 1080, margin: '0 auto', padding: '0 16px 10px', display: 'flex', gap: 6, flexWrap: 'wrap', alignItems: 'center' }}>
          <span style={S.pill(s1Open)}>● Shift 1 {masterOn ? '· Mode Master' : s1Open ? '· terbuka, tutup 21.00' : '· tertutup (batas 21.00)'}</span>
          <span style={S.pill(s2Open)}>● Shift 2 {masterOn ? '· Mode Master' : s2Open ? '· terbuka sekarang s/d 08.00' : '· besok 07.30–08.00 untuk kerja kemarin'}</span>
          {masterOn
            ? <span style={S.masterBadge}>Mode Master aktif</span>
            : null}
          <button
            type="button"
            style={{ ...S.btnSec, marginLeft: 'auto' }}
            onClick={() => { if (masterOn) { setMaster(false); showToast('Mode Master dimatikan — karyawan isi sesuai jendela shift.'); } else { setPinPanel(true); setPinMsg(''); setPin(''); } }}
          >
            {masterOn ? 'Kunci Mode Master' : 'Mode Master'}
          </button>
          {saving ? <span style={{ fontSize: 12, color: '#6b7280' }}>Menyimpan…</span> : null}
        </div>
      </header>

      <main style={S.main}>
        <div style={S.col}>

          {pinPanel && !masterOn && (
            <section style={S.panel} aria-label="Buka Mode Master">
              <h3 style={S.h3}>Mode Master</h3>
              <p style={S.hint}>Mode Master untuk mengisi atau membetulkan catatan di luar jendela shift — tanggal &amp; waktu bisa diatur manual dan jendela jam tidak berlaku. Karyawan tetap bisa isi sendiri tanpa PIN sesuai jendela shift yang berlaku.</p>
              <label style={S.label} htmlFor="pinInput">PIN Master</label>
              <input
                type="password" id="pinInput" inputMode="numeric" autoComplete="off" placeholder="Masukkan PIN"
                style={S.input} value={pin}
                onChange={(e) => setPin(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); tryUnlock(); } }}
              />
              {pinMsg ? <div style={S.err}>{pinMsg}</div> : null}
              <div style={{ display: 'flex', gap: 8 }}>
                <button type="button" style={S.btnSmall} onClick={tryUnlock}>Buka Mode Master</button>
                <button type="button" style={S.btnSec} onClick={() => setPinPanel(false)}>Batal</button>
              </div>
            </section>
          )}

          {/* ============ BERANDA ============ */}
          {tab === 'beranda' && (
            <div>
              <h1 style={S.h1}>Karyawan Aktif — Hasil Terbanyak</h1>
              <p style={S.lead}>{leadRange.label} · {leadReported} karyawan sudah melapor · {leadEntries.length} catatan</p>
              <div style={S.segWrap}>
                <button type="button" style={S.segBtn(leadPeriod === 'hari')} onClick={() => setLeadPeriod('hari')}>Hari Ini</button>
                <button type="button" style={S.segBtn(leadPeriod === 'minggu')} onClick={() => setLeadPeriod('minggu')}>Minggu Ini</button>
                <button type="button" style={S.segBtn(leadPeriod === 'bulan')} onClick={() => setLeadPeriod('bulan')}>Bulan Ini</button>
              </div>
              <div style={S.panel}>
                <h3 style={S.h3}>Peringkat per Karyawan</h3>
                {rankBlock(leadRank)}
                <p style={{ ...S.hint, margin: '12px 0 0' }}>Catatan “Tanpa hasil (keterangan saja)” tidak masuk total/peringkat, tetapi karyawannya tetap dihitung sudah melapor.</p>
              </div>

              <h2 style={{ ...S.h1, fontSize: 22, marginTop: 8 }}>Riwayat Lengkap</h2>
              <p style={S.lead}>{entries.length} catatan · terbaru di atas</p>
              {!historySorted.length && <div style={S.empty}>Belum ada catatan hasil kerja.</div>}
              {historySorted.map((e) => entryCard(e, true, startEditEntry, deleteEntry))}
            </div>
          )}

          {/* ============ INPUT HASIL ============ */}
          {tab === 'input' && (
            <form style={S.panel} onSubmit={submitWork} noValidate>
              <h3 style={S.h3}>{editId ? 'Ubah catatan hasil kerja' : 'Catatan hasil kerja baru'}</h3>
              <p style={S.hint}>Satu catatan bisa diisi beberapa nama bila pekerjaan dikerjakan bersama. Hasil boleh dikosongkan bila pekerjaan hanya berupa keterangan.</p>
              {!masterOn && (
                <div style={S.locknote}>
                  <strong>Karyawan bisa isi sendiri</strong> sesuai jendela shift: Shift 1 di hari kerja sampai pukul 21.00, Shift 2 besoknya pukul 07.30–08.00. Di luar jendela itu, pengisian hanya bisa lewat Mode Master.
                  <div style={{ marginTop: 8 }}>
                    <button type="button" style={S.btnSmall} onClick={() => { setPinPanel(true); setPinMsg(''); setPin(''); }}>Buka Mode Master</button>
                  </div>
                </div>
              )}
              <div style={S.grid2}>
                <div>
                  <label style={S.label} htmlFor="wdate">Tanggal kerja <span style={S.req}>*</span></label>
                  <input
                    type="date" id="wdate" style={S.input} value={effWorkDate}
                    disabled={!masterOn}
                    onChange={(e) => setFDate(e.target.value)}
                  />
                  {!masterOn && <p style={S.fieldHint}>Tanggal tercatat mengikuti shift yang dipilih{ fShift === 2 ? ' — Shift 2 tercatat untuk kerja kemarin.' : '.'}</p>}
                </div>
                {masterOn && (
                  <div>
                    <label style={S.label} htmlFor="wtime">Waktu (diisi manual)</label>
                    <input type="time" id="wtime" style={S.input} value={fTime} onChange={(e) => setFTime(e.target.value)} />
                  </div>
                )}
                <div>
                  <label style={S.label}>Shift <span style={S.req}>*</span></label>
                  <div style={S.segWrap}>
                    <button type="button" style={S.segBtn(fShift === 1)} onClick={() => setFShift(1)}>Shift 1</button>
                    <button type="button" style={S.segBtn(fShift === 2)} onClick={() => setFShift(2)}>Shift 2</button>
                    <button type="button" style={S.segBtn(fShift === '')} onClick={() => setFShift('')}>Tanpa Shift</button>
                  </div>
                  <p style={S.fieldHint}>
                    {fShift === 2
                      ? `Shift 2 — tercatat untuk ${fmtDateLong(effWorkDate)}; hanya bisa diisi 07.30–08.00 pagi setelah hari kerja.`
                      : fShift === ''
                        ? `Tanpa shift — mengikuti aturan Shift 1, tercatat untuk ${fmtDateLong(effWorkDate)}.`
                        : `Shift 1 — tercatat untuk ${fmtDateLong(effWorkDate)}; tutup 21.00 di hari kerja.`}
                  </p>
                </div>
              </div>
              <div>
                <label style={S.label} htmlFor="empnames">Nama Karyawan <span style={S.req}>*</span></label>
                <input
                  type="text" id="empnames" style={S.input} autoComplete="off"
                  placeholder="Ketik nama — pisahkan dengan koma bila lebih dari satu, cth. NOVI, FADIL, AYU"
                  value={fNames} onChange={(e) => setFNames(e.target.value)}
                />
              </div>
              <div>
                <label style={S.label} htmlFor="machine">Nama Mesin <span style={S.req}>*</span></label>
                <input
                  type="text" id="machine" style={S.input} autoComplete="off"
                  placeholder="Ketik nama mesin bila memakai mesin, cth. Mesin UV, Mesin Laser Cutting"
                  value={fMachine} onChange={(e) => setFMachine(e.target.value)}
                />
                <p style={S.fieldHint}>Contoh: Mesin Sablon, Mesin UV, Mesin Laser Cutting</p>
              </div>
              <div>
                <label style={S.label} htmlFor="job">Pekerjaan <span style={S.req}>*</span></label>
                <input
                  type="text" id="job" style={S.input} autoComplete="off"
                  placeholder="Ketik pekerjaan, cth. Packing PHOTOCARD (hanya photo)"
                  value={fJob} onChange={(e) => setFJob(e.target.value)}
                />
              </div>
              <div style={S.grid2}>
                <div>
                  <label style={S.label}>Hasil</label>
                  <div style={S.segWrap}>
                    <button type="button" style={S.segBtn(fMode === 'qty')} onClick={() => setFMode('qty')}>Ada hasil</button>
                    <button type="button" style={S.segBtn(fMode === 'note')} onClick={() => setFMode('note')}>Tanpa hasil (keterangan saja)</button>
                  </div>
                  <div style={{ display: 'flex', gap: 8, opacity: fMode === 'qty' ? 1 : 0.35 }}>
                    <input
                      type="number" min="0" step="any" inputMode="decimal" placeholder="Jumlah" aria-label="Jumlah hasil"
                      style={{ ...S.input, marginBottom: 10 }} value={fQty} disabled={fMode !== 'qty'}
                      onChange={(e) => setFQty(e.target.value)}
                    />
                    <select aria-label="Satuan hasil" style={{ ...S.input, width: 110, marginBottom: 10 }} value={fUnit} disabled={fMode !== 'qty'} onChange={(e) => setFUnit(e.target.value)}>
                      {UNITS.map((u) => <option key={u} value={u}>{u}</option>)}
                    </select>
                  </div>
                  {fMode === 'note' && <p style={S.fieldHint}>Keterangan wajib diisi. Catatan ini tidak masuk total/peringkat, tetapi karyawan tetap dihitung sudah melapor.</p>}
                </div>
                <div>
                  <label style={S.label} htmlFor="note">Keterangan{fMode === 'note' ? <span style={S.req}> *</span> : ''}</label>
                  <textarea id="note" style={S.textarea} placeholder="cth. 3.200 pcs mulai dari jam (07:30 - 20:30)" value={fNote} onChange={(e) => setFNote(e.target.value)} />
                </div>
              </div>
              {fMsg.text && <div style={fMsg.kind === 'err' ? S.err : S.ok}>{fMsg.text}</div>}
              <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                <button type="submit" style={S.btn}>{editId ? 'Simpan Perubahan' : 'Tambah Catatan'}</button>
                {editId && <button type="button" style={S.btnSec} onClick={() => resetWorkForm(true)}>Batalkan Edit</button>}
              </div>
            </form>
          )}

          {/* ============ DRIVER ============ */}
          {tab === 'driver' && (
            <form style={S.panel} onSubmit={submitDriver} noValidate>
              <h3 style={S.h3}>{dEditId ? 'Ubah catatan pengiriman driver' : 'Catatan pengiriman driver'}</h3>
              <p style={S.hint}>Catat pengiriman yang berangkat pada tanggal kerja ini.</p>
              {!masterOn && (
                <div style={S.locknote}>
                  <strong>Driver / helper bisa isi sendiri</strong> untuk pengiriman pada tanggal yang dipilih (tutup 21.00 WIB). Mode Master hanya diperlukan bila master perlu membetulkan atau menghapus catatan.
                  <div style={{ marginTop: 8 }}>
                    <button type="button" style={S.btnSmall} onClick={() => { setPinPanel(true); setPinMsg(''); setPin(''); }}>Buka Mode Master</button>
                  </div>
                </div>
              )}
              <div style={S.grid2}>
                <div>
                  <label style={S.label} htmlFor="ddate">Tanggal <span style={S.req}>*</span></label>
                  <input
                    type="date" id="ddate" style={S.input} value={masterOn ? (dDate || todayWIB()) : todayWIB()}
                    disabled={!masterOn}
                    onChange={(e) => setDDate(e.target.value)}
                  />
                  {!masterOn && <p style={S.fieldHint}>Pengiriman driver dicatat untuk hari ini dan tutup pukul 21.00 WIB.</p>}
                </div>
                <div>
                  <label style={S.label} htmlFor="dname">Nama driver / Helper (kenek) <span style={S.req}>*</span></label>
                  <input
                    type="text" id="dname" style={S.input} autoComplete="off"
                    placeholder="Nama driver / helper (kenek)"
                    value={dName} onChange={(e) => setDName(e.target.value)}
                  />
                </div>
                <div>
                  <label style={S.label} htmlFor="ddest">Tujuan pengiriman <span style={S.req}>*</span></label>
                  <input
                    type="text" id="ddest" style={S.input} autoComplete="off"
                    placeholder="cth. Customer / gudang tujuan"
                    value={dDest} onChange={(e) => setDDest(e.target.value)}
                  />
                </div>
                <div>
                  <label style={S.label} htmlFor="dveh">Kendaraan / no. polisi</label>
                  <input
                    type="text" id="dveh" style={S.input} autoComplete="off"
                    placeholder="Boleh dikosongkan"
                    value={dVeh} onChange={(e) => setDVeh(e.target.value)}
                  />
                </div>
                <div style={{ gridColumn: '1 / -1' }}>
                  <label style={S.label} htmlFor="dnote">Keterangan</label>
                  <textarea id="dnote" style={S.textarea} placeholder="cth. Muatan, jam berangkat, atau catatan lain" value={dNote} onChange={(e) => setDNote(e.target.value)} />
                </div>
              </div>
              {dMsg.text && <div style={dMsg.kind === 'err' ? S.err : S.ok}>{dMsg.text}</div>}
              <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                <button type="submit" style={S.btn}>{dEditId ? 'Simpan Perubahan' : 'Tambah Pengiriman'}</button>
                {dEditId && <button type="button" style={S.btnSec} onClick={() => { setDEditId(null); setDName(''); setDDest(''); setDVeh(''); setDNote(''); setDMsg({ kind: '', text: '' }); }}>Batalkan Edit</button>}
              </div>
              <div style={{ marginTop: 24 }}>
                <h3 style={{ ...S.h3, fontSize: 15 }}>Pengiriman pada {fmtDateLong(masterOn ? (dDate || todayWIB()) : todayWIB())}</h3>
                {driverEntries.filter((d) => d.date === (masterOn ? (dDate || todayWIB()) : todayWIB())).length === 0
                  ? <div style={S.empty}>Belum ada pengiriman yang dicatat pada tanggal ini.</div>
                  : driverEntries.filter((d) => d.date === (masterOn ? (dDate || todayWIB()) : todayWIB())).map((d) => (
                    <div key={d.id} style={S.entry}>
                      <div style={S.job}>{d.name} → {d.dest}</div>
                      <div style={S.who}>{d.veh ? `Kendaraan: ${d.veh}` : 'Pengiriman driver'}</div>
                      {d.note ? <div style={S.note}>Keterangan: {d.note}</div> : null}
                      <div style={{ display: 'flex', gap: 8, marginTop: 10 }}>
                        <button type="button" style={S.btnSec} onClick={() => startEditDriver(d)}>Edit</button>
                        {masterOn && <button type="button" style={S.btnDanger} onClick={() => deleteDriver(d.id)}>Hapus</button>}
                      </div>
                    </div>
                  ))}
              </div>
            </form>
          )}

          {/* ============ HASIL (REKAP) ============ */}
          {tab === 'rekap' && (
            <div style={S.panel}>
              <h3 style={S.h3}>Rekap Hasil Kerja</h3>
              <div style={{ marginBottom: 14 }}>
                <label style={S.label}>Tampilan catatan</label>
                <div style={S.segWrap}>
                  <button type="button" style={S.segBtn(rekapMode === 'day')} onClick={() => setRekapMode('day')}>Per Hari</button>
                  <button type="button" style={S.segBtn(rekapMode === 'week')} onClick={() => setRekapMode('week')}>Per Minggu</button>
                </div>
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '0 16px' }}>
                <div>
                  <label style={S.label} htmlFor="rdate">{period.mode === 'week' ? 'Tanggal dalam minggu' : 'Tanggal rekap'}</label>
                  <input type="date" id="rdate" style={S.input} value={rdate} onChange={(e) => setRdate(e.target.value)} />
                </div>
                <div>
                  <label style={S.label} htmlFor="rsearch">Cari nama karyawan</label>
                  <input type="text" id="rsearch" style={S.input} autoComplete="off" placeholder="Ketik nama, cth. NOVI — kosongkan untuk semua" value={rsearch} onChange={(e) => setRsearch(e.target.value)} />
                </div>
                <div>
                  <label style={S.label} htmlFor="rmachine">Cari nama mesin</label>
                  <input type="text" id="rmachine" style={S.input} autoComplete="off" placeholder="Ketik nama mesin, cth. Mesin UV — kosongkan untuk semua" value={rmachine} onChange={(e) => setRmachine(e.target.value)} />
                </div>
              </div>
              <p style={{ fontSize: 14, color: '#111827', margin: '4px 0 12px' }}>
                {period.mode === 'week' ? 'Menampilkan per minggu (Senin–Minggu): ' : 'Menampilkan per hari: '}
                <b>{period.label}</b>
                {period.mode === 'week' ? ' — pilih hari apa saja di dalam minggu itu.' : ''}
              </p>
              {(qName || qMachine) && (
                <p style={{ fontSize: 13, color: '#4b5563' }}>
                  Pencarian {qName ? `nama karyawan “${rsearch.trim()}”` : ''}{qName && qMachine ? ' dan ' : ''}{qMachine ? `nama mesin “${rmachine.trim()}”` : ''} — ditemukan <b>{periodEntries.length}</b> catatan hasil kerja. Total, peringkat, dan unduhan di bawah hanya untuk catatan yang cocok. Pengiriman driver tidak ikut difilter.
                </p>
              )}

              {period.mode === 'week' && (
                <div>
                  <div style={S.secttl}>Ringkasan per Hari dalam Minggu</div>
                  <ul style={{ margin: 0, paddingLeft: 0, listStyle: 'none' }}>
                    {period.dates.map((dstr) => {
                      const dayList = periodEntries.filter((e) => e.date === dstr);
                      return (
                        <li key={dstr} style={{ display: 'flex', justifyContent: 'space-between', gap: 10, padding: '6px 0', borderBottom: '1px solid #f3f4f6', fontSize: 14 }}>
                          <span>{fmtDateLong(dstr)}</span>
                          <span style={{ fontWeight: 600 }}>{dayList.length ? `${dayList.length} catatan — ${totalsText(totalsOf(dayList))}` : 'Tidak ada catatan'}</span>
                        </li>
                      );
                    })}
                  </ul>
                </div>
              )}

              <div style={S.secttl}>Shift 1 — {s1.length} catatan{period.mode === 'week' ? ' (minggu ini)' : ''}</div>
              {!s1.length && <div style={S.empty}>Belum ada catatan Shift 1{period.mode === 'week' ? ' pada minggu ini.' : ' pada tanggal ini.'}{(qName || qMachine) ? ' untuk pencarian yang aktif.' : ''}</div>}
              {s1.map((e) => entryCard(e, period.mode === 'week', startEditEntry, deleteEntry))}
              {s1.length > 0 && <div style={S.totals}>Total: <b>{totalsText(totalsOf(s1))}</b></div>}

              <div style={S.secttl}>Shift 2 — {s2.length} catatan{period.mode === 'week' ? ' (minggu ini)' : ''}</div>
              {!s2.length && <div style={S.empty}>Belum ada catatan Shift 2{period.mode === 'week' ? ' pada minggu ini.' : ' pada tanggal ini.'}{(qName || qMachine) ? ' untuk pencarian yang aktif.' : ''}</div>}
              {s2.map((e) => entryCard(e, period.mode === 'week', startEditEntry, deleteEntry))}
              {s2.length > 0 && <div style={S.totals}>Total: <b>{totalsText(totalsOf(s2))}</b></div>}

              <div style={S.secttl}>Pengiriman Driver — {periodDrivers.length} catatan{period.mode === 'week' ? ' (minggu ini)' : ''}</div>
              {!periodDrivers.length && <div style={S.empty}>{period.mode === 'week' ? 'Tidak ada pengiriman driver yang dicatat pada minggu ini.' : 'Tidak ada pengiriman driver yang dicatat pada tanggal ini.'}</div>}
              {periodDrivers.map((d) => (
                <div key={d.id} style={S.entry}>
                  {period.mode === 'week' && <span style={S.dateTag}>{fmtDateLong(d.date)}</span>}
                  <div style={S.job}>{d.name} → {d.dest}</div>
                  <div style={S.who}>{d.veh ? `Kendaraan: ${d.veh}` : 'Pengiriman driver'}</div>
                  {d.note ? <div style={S.note}>Keterangan: {d.note}</div> : null}
                  <div style={{ display: 'flex', gap: 8, marginTop: 10 }}>
                    <button type="button" style={S.btnSec} onClick={() => startEditDriver(d)}>Edit</button>
                    {masterOn && <button type="button" style={S.btnDanger} onClick={() => deleteDriver(d.id)}>Hapus</button>}
                  </div>
                </div>
              ))}

              <div style={S.secttl}>{period.mode === 'week' ? 'Peringkat per Karyawan — Minggu Ini (gabungan Shift 1 + 2)' : 'Peringkat per Karyawan (gabungan Shift 1 + 2)'}</div>
              {rankBlock(rekapRank)}

              <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginTop: 20 }}>
                <button type="button" style={S.btnSmall} onClick={downloadTxt}>Unduh Laporan (.txt)</button>
                <button type="button" style={S.btnSec} onClick={copyReport}>Salin Laporan</button>
                <button type="button" style={S.btnSec} onClick={downloadCsv}>Unduh CSV</button>
                <button type="button" style={S.btnSec} onClick={downloadXlsx}>Unduh Excel (.xlsx)</button>
              </div>
              <p style={{ ...S.hint, margin: '12px 0 0' }}>Unduhan &amp; salinan mengikuti tampilan yang dipilih (per hari / per minggu) dan pencarian (nama karyawan / nama mesin) yang aktif di atas. File Excel berisi 3 sheet: <strong>Hasil Kerja</strong>, <strong>Driver</strong>, dan <strong>Ringkasan</strong> (total &amp; peringkat).</p>
            </div>
          )}

        </div>
      </main>

      <footer style={{ textAlign: 'center', fontSize: 12, color: '#6b7280', padding: '0 16px 24px' }}>
        Hasil Kerja Karyawan — PT. Meleo Mahkota Abadi · Data tersimpan di server, bisa dibuka dari perangkat apa saja.
      </footer>
      {toast && <div style={S.toast} role="status">{toast}</div>}
    </div>
  );
}
